import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate report type
        if (reportType == null || !reportType.matches("(sales|inventory|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (!isValidDate(dateFrom) || !isValidDate(dateTo)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_ORDER.matcher(sortCol).matches()) {
            sortCol = "created_at";
        }

        // Build query - dates are validated, sort is regex-checked
        // Filter allows complex expressions for power users
        String query = buildReportQuery(reportType, dateFrom, dateTo, sortCol, filterExpr);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><body><table>");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + StringEscapeUtils.escapeHtml4(meta.getColumnName(i)) + "</th>");
            }
            out.println("</tr>");

            while (rs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + StringEscapeUtils.escapeHtml4(rs.getString(i)) + "</td>");
                }
                out.println("</tr>");
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String from, String to, 
                                     String sort, String filter) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM report_").append(type);
        sb.append(" WHERE created_at BETWEEN '").append(from).append("' AND '").append(to).append("'");

        if (filter != null && !filter.isEmpty()) {
            // Power user filter - allows SQL expressions for flexible reporting
            sb.append(" AND (").append(filter).append(")");
        }

        if (sort != null) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }

    private boolean isValidDate(String d) {
        if (d == null) return false;
        return d.matches("\\d{4}-\\d{2}-\\d{2}");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    private static class PrintWriter extends java.io.PrintWriter {
        PrintWriter(java.io.Writer w) { super(w); }
    }
}
